export interface DigestionMeasurements {
  pulseAvg: number | null;
  systolic: number | null;
  diastolic: number | null;
  weightAvg: number | null;
  weightDelta: number | null;
  tonus: 'low' | 'normal' | 'high' | 'no_data';
  triad: {
    wellbeing: 'bad' | 'normal' | 'good';
    energy: 'low' | 'normal' | 'high';
    mood: 'bad' | 'normal' | 'good';
  } | null;
}

export interface DigestionContext {
  userName: string;
  userGender?: 'male' | 'female';
  worstBristol: number;
  latestComfort: 'easy' | 'normal' | 'hard' | null;
  problemDishName?: string;
  symptoms: string[];
  latestSymptoms: string[];
  waterStatus: 'zero' | 'deficit' | 'optimum' | 'excess';
  movementStatus: 'sedentary' | 'light' | 'active' | 'athlete';
  latestMeasurements?: DigestionMeasurements;
  /** Optional facts provided by the next digestion engine. */
  dayIndex?: number;
  isCurrentDay?: boolean;
  bristolTypes?: number[];
  episodeCount?: number;
  volume?: 'scanty' | 'normal' | 'voluminous' | null;
  explicitNoSymptoms?: boolean;
  waterAmount?: number | null;
  waterHasEntries?: boolean;
  movementMinutes?: number | null;
  movementHasEntries?: boolean;
  yesterdayFiber?: number | null;
  /** Additional optional input contract for the next engine is declared below. */
}

export const getRandomPhrase = (phrases: string[], ctx: DigestionContext): string => {
  if (!phrases || phrases.length === 0) return '';
  const seed = JSON.stringify([
    ctx.dayIndex ?? null, ctx.isCurrentDay ?? null, ctx.bristolTypes ?? null,
    ctx.episodeCount ?? null, ctx.volume ?? null, ctx.explicitNoSymptoms ?? null,
    ctx.worstBristol, ctx.latestComfort, ctx.symptoms, ctx.latestSymptoms,
    ctx.waterStatus, ctx.waterAmount ?? null, ctx.waterHasEntries ?? null,
    ctx.movementStatus, ctx.movementMinutes ?? null, ctx.movementHasEntries ?? null,
    ctx.yesterdayFiber ?? null, ctx.problemDishName ?? null,
    ctx.latestMeasurements ?? null, phrases[0],
  ]);
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return phrases[(hash >>> 0) % phrases.length]
    .replace(/{name}/g, ctx.userName ?? '')
    .replace(/{problemDishName}/g, ctx.problemDishName ?? 'блюдо')
    .replace(/{symptoms}/g, (ctx.latestSymptoms ?? []).map((symptom) => {
      const labels: Record<string, string> = {
        bloating: 'вздутие', cramps: 'спазмы', pain: 'боль', nausea: 'тошнота',
        heartburn: 'изжога', diarrhea: 'диарея', constipation: 'запор',
        mucus: 'слизь', blood: 'кровь', rumbling: 'урчание', gas: 'газы',
        incomplete: 'ощущение неполного опорожнения', none: 'нет симптомов',
      };
      const label = labels[symptom.trim().toLowerCase()] ?? symptom;
      return /[a-z]/i.test(label) ? 'отмеченное ощущение' : label;
    }).join(', '));
};

