/** Contract for a future router. None of these optional fields is read by the
 * current phrase selection, and merely adding them does NOT connect routes. */
export interface DigestionEpisodeEvidence {
  /** Stable identifier of the saved episode, if present. */
  id?: string;
  dayIndex: number;
  /** Actual event time only when explicitly verified; save time is not event time. */
  eventAt?: string | null;
  bristol: 1 | 2 | 3 | 4 | 5 | 6 | 7 | null;
  volume: 'scanty' | 'normal' | 'voluminous' | null;
  passage: 'easy' | 'hard' | null;
  /** unselected and explicit_none MUST NOT be collapsed into the same value. */
  symptomAnswer: 'unselected' | 'explicit_none' | 'selected';
  symptoms: string[];
}

export interface DigestionDatedMeasurements {
  dayIndex: number;
  /** A pair must come from one reading, not two unrelated readings. */
  pressureReadings?: Array<{ systolic: number | null; diastolic: number | null; recordedAt?: string | null }>;
  pulseReadings?: Array<{ bpm: number; recordedAt?: string | null; atRest?: boolean | null }>;
  tonus?: 'low' | 'normal' | 'high' | 'no_data';
  triad?: DigestionMeasurements['triad'];
}

export interface DigestionDishEvidence {
  id: string;
  dayIndex: number; // selected dayIndex - 1 for the ordinary GI food route
  name: string;
  eatenAt?: string | null; // validated createdAt: preparation AND eating by product contract
  portionGrams?: number | null;
  fiberGrams?: number | null; // unknown must remain null; no inferred zero
  ingredients: Array<{ name: string; grams?: number | null; status?: 'green' | 'red' | 'unknown'; fiberGrams?: number | null }>;
  /** True only when all relevant saved nutrient values are reliable. */
  nutrientsComplete?: boolean;
}

export interface DigestionWaterEvidence {
  dayIndex: number;
  hasEntries: boolean;
  entryCount: number;
  amountMl: number | null; // null for no known amount; not a proxy for no drinking
  goalMl?: number | null;
  dayGoalPercent?: number | null;
  /** Today only. Distinct denominator from dayGoalPercent. */
  timeGoalPercent?: number | null;
}

export interface DigestionMovementEvidence {
  dayIndex: number;
  hasEntries: boolean;
  entryCount: number;
  activeMinutes: number | null;
  goalReached?: boolean | null;
  activityTypes?: string[];
}

/** Future-engine additions to DigestionContext (all optional for existing callers). */
export interface DigestionContext {
  episodesForSelectedDay?: DigestionEpisodeEvidence[];
  latestEpisodeId?: string | null;
  validBristolAverage?: number | null;
  mostDifferentBristol?: number | null;
  symptomsByEpisode?: Array<{ episodeId: string; symptoms: string[] }>;
  dailyMeasurements?: DigestionDatedMeasurements | null;
  selectedDayWater?: DigestionWaterEvidence;
  selectedDayMovement?: DigestionMovementEvidence;
  previousDayDishes?: DigestionDishEvidence[];
  /** The router alone chooses current vs historical variants. */
  isHistoricalDay?: boolean;
}
